<?php
$all=require __DIR__.'/modules.php'; $m=$all[$page]; $table=$m['table']; $pk=$m['pk'];
$editId=filter_input(INPUT_GET,'edit',FILTER_VALIDATE_INT) ?: null;
if(isset($_GET['delete'])) { if($_SERVER['REQUEST_METHOD']!=='POST') { http_response_code(405); exit('Use the confirmation form to delete records.'); } check_csrf(); $id=(int)$_POST['id']; $st=db()->prepare("DELETE FROM \"$table\" WHERE \"$pk\"=?"); $st->execute([$id]); audit('DELETE',$table,$id); flash('success',$m['title'].' record deleted.'); go('page='.$page); }
if($_SERVER['REQUEST_METHOD']==='POST') { check_csrf(); $id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT)?:null; $data=[]; foreach($m['fields'] as [$key,$label,$type,$required]) { $v=trim((string)($_POST[$key]??'')); if($required && $v==='') { flash('danger',"$label is required."); go('page='.$page.($id?'&edit='.$id:'')); } $data[$key]=$v===''?null:$v; } try { if($id) { $assign=implode(',',array_map(fn($c)=>'"'.$c.'"=?',array_keys($data))); $vals=array_values($data); $vals[]=$id; $st=db()->prepare("UPDATE \"$table\" SET $assign, updated_at=now() WHERE \"$pk\"=?"); $st->execute($vals); audit('UPDATE',$table,$id); flash('success',$m['title'].' updated.'); } else { $cols=implode(',',array_map(fn($c)=>'"'.$c.'"',array_keys($data))); $marks=implode(',',array_fill(0,count($data),'?')); $st=db()->prepare("INSERT INTO \"$table\" ($cols) VALUES ($marks) RETURNING \"$pk\""); $st->execute(array_values($data)); $new=(int)$st->fetchColumn(); audit('CREATE',$table,$new); flash('success',$m['title'].' created.'); } } catch(PDOException $e) { if($e->getCode()==='23503') flash('danger','Select a valid related record.'); elseif($e->getCode()==='23514') flash('danger','One or more values do not meet the data rules.'); else throw $e; go('page='.$page); } go('page='.$page); }
$record=null; if($editId) { $st=db()->prepare("SELECT * FROM \"$table\" WHERE \"$pk\"=?"); $st->execute([$editId]); $record=$st->fetch(); }
$search=trim($_GET['q']??''); $sort=$_GET['sort']??$pk; $allowedSort=array_merge([$pk],array_map(fn($f)=>$f[0],$m['fields'])); if(!in_array($sort,$allowedSort,true)) $sort=$pk; $dir=strtolower($_GET['dir']??'desc')==='asc'?'ASC':'DESC'; $where=''; $params=[]; if($search && $m['search']) { $where='WHERE '.implode(' OR ',array_map(fn($c)=>"CAST(\"$c\" AS TEXT) ILIKE ?",$m['search'])); $params=array_fill(0,count($m['search']),'%'.$search.'%'); }
$count=db()->prepare("SELECT COUNT(*) FROM \"$table\" $where"); $count->execute($params); $total=(int)$count->fetchColumn(); $per=10; $pages=max(1,(int)ceil($total/$per)); $current=max(1,min($pages,(int)($_GET['p']??1))); $st=db()->prepare("SELECT * FROM \"$table\" $where ORDER BY \"$sort\" $dir LIMIT $per OFFSET ".(($current-1)*$per)); $st->execute($params); $rows=$st->fetchAll();
$refs=[]; foreach($m['fields'] as [$key,$label,$type]) if(str_starts_with($type,'ref:')) { $rt=substr($type,4); $name=match($rt){'farmer'=>"first_name || ' ' || last_name",'farm'=>'farm_name','crop'=>'crop_name','planting'=>"'Planting #' || planting_id",'harvest_remark'=>'description',default=>'id'}; $idcol=match($rt){'farmer'=>'farmer_id','farm'=>'farm_id','crop'=>'crop_id','planting'=>'planting_id','harvest_remark'=>'remark_id',default=>'id'}; $refs[$key]=db()->query("SELECT $idcol id, $name label FROM $rt ORDER BY label")->fetchAll(); }
$editRecord=$record; $layoutTitle=$m['title']; require __DIR__.'/views/layout-top.php';
?>
<section class="section pt-5"><div class="container"><div class="level"><div><p class="eyebrow">DATA MANAGEMENT</p><h1 class="title is-3"><?=e($m['title'])?></h1><p class="subtitle is-6">Create, search, update, and remove records.</p></div></div>
<div class="columns is-variable is-5"><div class="column is-4"><div class="box form-card"><h2 class="title is-5"><?=$record?'Edit':'Add'?> <?=e(rtrim($m['title'],'s'))?></h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=e($record[$pk]??'')?>">
<?php foreach($m['fields'] as [$key,$label,$type,$required]): ?><div class="field"><label class="label" for="<?=e($key)?>"><?=e($label)?></label><div class="control">
<?php if(str_starts_with($type,'ref:')): ?><div class="select is-fullwidth"><select id="<?=e($key)?>" name="<?=e($key)?>" <?=$required?'required':''?>><option value="">Choose?</option><?php foreach($refs[$key] as $o): ?><option value="<?=e($o['id'])?>" <?=((string)($record[$key]??'')===(string)$o['id'])?'selected':''?>><?=e($o['label'])?></option><?php endforeach ?></select></div>
<?php elseif(str_starts_with($type,'select:')): $lookup=substr($type,7); $opts=db()->query("SELECT code,label FROM $lookup ORDER BY sort_order,label")->fetchAll(); ?><div class="select is-fullwidth"><select id="<?=e($key)?>" name="<?=e($key)?>" <?=$required?'required':''?>><option value="">Choose?</option><?php foreach($opts as $o): ?><option value="<?=e($o['code'])?>" <?=((string)($record[$key]??'')===$o['code'])?'selected':''?>><?=e($o['label'])?></option><?php endforeach ?></select></div>
<?php else: ?><input class="input" id="<?=e($key)?>" name="<?=e($key)?>" type="<?=e($type==='number'?'number':$type)?>" <?=($type==='number'?'step="0.01" min="0"':'')?> value="<?=e($record[$key]??'')?>" <?=$required?'required':''?>><?php endif ?></div></div><?php endforeach ?>
<div class="buttons"><button class="button is-primary">Save record</button><?php if($record): ?><a class="button is-light" href="<?=e(url('page='.$page))?>">Cancel</a><?php endif ?></div></form></div></div>
<div class="column"><div class="box table-card"><form method="get" class="field has-addons"><input type="hidden" name="page" value="<?=e($page)?>"><div class="control"><div class="select"><select name="sort"><?php foreach(array_merge([$pk],array_map(fn($f)=>$f[0],$m['fields'])) as $col): ?><option value="<?=e($col)?>" <?=$sort===$col?'selected':''?>><?=e(ucwords(str_replace('_',' ',$col)))?></option><?php endforeach ?></select></div></div><div class="control"><div class="select"><select name="dir"><option value="desc" <?=$dir==='DESC'?'selected':''?>>Descending</option><option value="asc" <?=$dir==='ASC'?'selected':''?>>Ascending</option></select></div></div><div class="control is-expanded"><input class="input" name="q" placeholder="Search records" value="<?=e($search)?>"></div><div class="control"><button class="button">Search</button></div></form><div class="table-container"><table class="table is-fullwidth is-hoverable"><thead><tr><th>ID</th><?php foreach($m['fields'] as [$key,$label]): ?><th><?=e($label)?></th><?php endforeach ?><th></th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><?=e($row[$pk])?></td><?php foreach($m['fields'] as [$key,$label,$type]): ?><td><?php if(str_starts_with($type,'ref:')): $opt=array_filter($refs[$key],fn($x)=>(string)$x['id']===(string)$row[$key]); echo e(reset($opt)['label']??'?'); elseif(str_starts_with($type,'select:')): $opt=db()->prepare('SELECT label FROM '.substr($type,7).' WHERE code=?'); $opt->execute([$row[$key]]); echo e($opt->fetchColumn()?:'?'); else: echo e($row[$key]??'?'); endif ?></td><?php endforeach ?><td class="actions"><a class="button is-small is-light" href="<?=e(url('page='.$page.'&edit='.$row[$pk]))?>">Edit</a><form method="post" action="<?=e(url('page='.$page.'&delete=1'))?>" onsubmit="return confirm('Delete this record? Related records may also be deleted.');"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=e($row[$pk])?>"><button class="button is-small is-danger is-light">Delete</button></form></td></tr><?php endforeach ?><?php if(!$rows): ?><tr><td colspan="<?=count($m['fields'])+2?>" class="has-text-centered has-text-grey">No records found.</td></tr><?php endif ?></tbody></table></div><nav class="pagination is-right"><a class="pagination-previous" <?=$current<=1?'disabled':''?> href="<?=e(url('page='.$page.'&p='.max(1,$current-1).'&q='.urlencode($search).'&sort='.urlencode($sort).'&dir='.urlencode(strtolower($dir))))?>">Previous</a><a class="pagination-next" <?=$current>=$pages?'disabled':''?> href="<?=e(url('page='.$page.'&p='.min($pages,$current+1).'&q='.urlencode($search).'&sort='.urlencode($sort).'&dir='.urlencode(strtolower($dir))))?>">Next</a><span class="pagination-list">Page <?=$current?> of <?=$pages?> ? <?=$total?> records</span></nav></div></div></div></div></section>
<?php require __DIR__.'/views/layout-bottom.php'; ?>
